#include <iostream>
#include <vector>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long q;
    cin >> n >> q;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    vector<long long> ks(q);
    for (int i = 0; i < q; i++) cin >> ks[i];

    long long basis[60] = {0};
    for (long long x : a) {
        for (int bit = 59; bit >= 0; bit--) {
            if (!((x >> bit) & 1)) continue;
            if (basis[bit] == 0) {
                basis[bit] = x;
                break;
            }
            x ^= basis[bit];
        }
    }
    for (int i = 0; i < 60; i++) {
        if (!basis[i]) continue;
        for (int j = i + 1; j < 60; j++) {
            if ((basis[j] >> i) & 1) basis[j] ^= basis[i];
        }
    }
    vector<long long> vs;
    for (int i = 0; i < 60; i++) if (basis[i]) vs.push_back(basis[i]);
    int r = (int)vs.size();
    for (long long t = 0; t < q; t++) {
        long long k = ks[t], result;
        if (k > (1LL << r)) {
            result = -1;
        } else {
            long long idx = k - 1;
            result = 0;
            for (int s = 0; s < r; s++) if ((idx >> s) & 1) result ^= vs[s];
        }
        cout << (t ? " " : "") << result;
    }
    cout << "\n";

    return 0;
}

