import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[] ks = new long[(int) q];
        for (int i = 0; i < ks.length; i++) ks[i] = Long.parseLong(next());

        long[] basis = new long[60];
        for (long v : a) {
            long x = v;
            for (int bit = 59; bit >= 0; bit--) {
                if (((x >> bit) & 1L) == 0) continue;
                if (basis[bit] == 0) {
                    basis[bit] = x;
                    break;
                }
                x ^= basis[bit];
            }
        }
        for (int i = 0; i < 60; i++) {
            if (basis[i] == 0) continue;
            for (int j = i + 1; j < 60; j++) {
                if (((basis[j] >> i) & 1L) != 0) basis[j] ^= basis[i];
            }
        }
        long[] vs = new long[60];
        int r = 0;
        for (int i = 0; i < 60; i++) if (basis[i] != 0) vs[r++] = basis[i];
        StringBuilder out = new StringBuilder();
        for (int t = 0; t < q; t++) {
            long k = ks[t], result;
            if (k > (1L << r)) {
                result = -1;
            } else {
                long idx = k - 1;
                result = 0;
                for (int s = 0; s < r; s++) if (((idx >> s) & 1L) != 0) result ^= vs[s];
            }
            if (t > 0) out.append(" ");
            out.append(result);
        }
        System.out.println(out);
    }
}
